import{_ as e,c as r,o as p,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"56、【旅】 艮下離上","description":"周易尚氏學 - 56、【旅】 艮下離上","frontmatter":{"title":"56、【旅】 艮下離上","description":"周易尚氏學 - 56、【旅】 艮下離上"},"headers":[],"relativePath":"classics/shangshi/061.md","filePath":"classics/shangshi/061.md"}'),s={name:"classics/shangshi/061.md"};function t(h,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_56、【旅】-艮下離上" tabindex="-1">56、【旅】 艮下離上 <a class="header-anchor" href="#_56、【旅】-艮下離上" aria-label="Permalink to “56、【旅】 艮下離上”">​</a></h1><p>旅之卦義。先儒皆以行旅為說。然卦名皆由卦象生。火山何以為旅。侯果孔疏皆以火在山上。勢難久留。故為旅。如所詁火在山上。不久即滅耳。安見其為行旅。按易林剝之旅雲。居正不安。大盜為咎。大畜之旅雲。安其室廬。傳母何優。是皆以居家為說。於行旅之義正相反。履之旅雲。鳥子鵲雛。常與母俱。願慕群旅。不離其巢。又晉之旅雲。逐旅失群。是以旅為伴旅。卦二陰。隨二陽。一陰隨一陽。陽前陰後。有若伴侶。疑焦氏所詁者。於卦象為切。又釋詁旅眾也。卦離火。艮亦為火。火多故眾。伴旅亦眾也。九三象雲。以旅與下。以眾與下也。若作行旅。此句難通矣。又初交旅瑣瑣。斯其所。斯離也。行旅往來。有不離其所者哉。於行旅之義尤不合。故疑焦義是也。六五得尊位。故小亨。貞吉。</p><p>彖曰。旅。小亨。柔得中乎外而順乎剛。上而麗乎明。是以小亨。旅貞吉也。旅之時又大矣哉。</p><p>六五上下皆陽。故曰順乎剛。離六五雲。離王公。即順乎剛也。旅五月卦。當中夏。故曰時。</p><p>象曰。山上有火。旅。君子以明慎用刑。而不留獄。</p><p>大象以相反見義。此亦其一也。離為明。君子不敢待其明。故用刑必慎。艮為慎。兌為刑也。艮為止。君子不敢怠於事。故不留獄。艮為拘繫為獄也。</p><p>初六。旅瑣瑣。斯其所取災。</p><p>瑣瑣。陸績鄭玄皆訓為小。馬雲疲弊視貌。按爾雅釋詁。瑣瑣小也。注舍人曰瑣瑣。計謀褊淺之貌。詩節南山。瑣瑣姻姬。蓋往來猥瑣。勞弊不安也。斯釋言離也。斯其所言離其所欲應四也。二得敵。故取災。離為災。蓋初六不當位。而得敵。在下。宜靜不宜動。故易林復之旅雲。二人輦車。徒去其家。井沸釜鳴。不可以居。徒去其家。即離其所。並沸釜鳴。即取災也。義詳焦氏易詁。</p><h3 id="象曰。旅瑣瑣。志窮變也。" tabindex="-1">象曰。旅瑣瑣。志窮變也。 <a class="header-anchor" href="#象曰。旅瑣瑣。志窮變也。" aria-label="Permalink to “象曰。旅瑣瑣。志窮變也。”">​</a></h3><p>初不當位。二得敵。不能應四。故曰志窮。</p><p>六二。旅即次。懷其資。得僮僕貞。</p><p>舉正作員吉。宜從。艮為舍。次舍也。即次。言就舍也。資財也。巽為利居中。故懷其資。艮為僮僕。二得位承陽。故得僮僕。貞下宜依舉正增吉字。貞吉與下貞厲為對文。</p><h3 id="象曰。得童僕貞-終無尤也。" tabindex="-1">象曰。得童僕貞，終無尤也。 <a class="header-anchor" href="#象曰。得童僕貞-終無尤也。" aria-label="Permalink to “象曰。得童僕貞，終無尤也。”">​</a></h3><p>即次身安。懷資用足。得僮僕役使有人。故終天尤。艮初象雲。志疑也。即以巽為志。雜卦雲。巽伏也。心志伏在內。故巽象之。舊解命四變成坎取心象。非。</p><p>九三：旅焚其次，喪其童僕，貞厲。</p><h3 id="象曰-旅焚其次-亦以傷矣。以旅與下-其義喪也。" tabindex="-1">象曰：旅焚其次，亦以傷矣。以旅與下，其義喪也。 <a class="header-anchor" href="#象曰-旅焚其次-亦以傷矣。以旅與下-其義喪也。" aria-label="Permalink to “象曰：旅焚其次，亦以傷矣。以旅與下，其義喪也。”">​</a></h3><p>九四：旅於處，得其資斧，我心不快。</p><h3 id="象曰-旅於處-未得位也。得其資斧-心未快也。" tabindex="-1">象曰：旅於處，未得位也。得其資斧，心未快也。 <a class="header-anchor" href="#象曰-旅於處-未得位也。得其資斧-心未快也。" aria-label="Permalink to “象曰：旅於處，未得位也。得其資斧，心未快也。”">​</a></h3><p>凡九四比六五。例終升五。歸妹九四曰。有待而行。待升五也。豐九四曰遇其夷主吉行也。六五曰來章。亦言回來五也。茲曰未得位。因未得五位。故處以俟也。下六五曰終以譽命。即謂四終升五也。</p><p>六五。射雉。一矢亡。終以譽命。</p><p>離為雉。兌毀折。故射雉。射必以矢。坎為矢。乃坎伏不見。故一矢亡。坎數一也。譽令聞也。艮為譽。命。爵命也。巽為命。終以譽命者。言巽命在二。雖不應五。然四必得位升五。四升五。二應之。是譽命終及於五也。</p><h3 id="象曰。終以譽命。上逮也。" tabindex="-1">象曰。終以譽命。上逮也。 <a class="header-anchor" href="#象曰。終以譽命。上逮也。" aria-label="Permalink to “象曰。終以譽命。上逮也。”">​</a></h3><p>逮及也。上逮謂二終上應五也。</p><p>上九：鳥焚其巢，旅人先笑後號咷，喪牛於易，兇。</p><p>離為鳥。中虛故為巢。巽風扇火於下故焚巢。上履陰。兌悅故先笑。三巽體。男為兆（左口）。三不應上。故後號兆。左傳昭五年。純離為牛。兌毀折。故喪牛。艮為田為易。易田畔電。牛在艮外。故喪牛于田畔。焚巢喪牛故兇。晁說之雲。易古文場字。詩小雅疆場有瓜是也。</p><h3 id="象曰-以旅在上-其義焚也。喪牛於易-終莫之聞也。" tabindex="-1">象曰：以旅在上，其義焚也。喪牛於易，終莫之聞也。 <a class="header-anchor" href="#象曰-以旅在上-其義焚也。喪牛於易-終莫之聞也。" aria-label="Permalink to “象曰：以旅在上，其義焚也。喪牛於易，終莫之聞也。”">​</a></h3><p>旅眾也。在上者眾。不自斂抑。則高亢為禍。左傳隱四年。兵猶火也。不戢將自焚。是其義也。坎為耳。坎伏故莫之聞。虞翻用爻變取震象。謂震為筐故為巢。後儒多從之。按易林離之需雲。高木腐巢需坎為木。在上故曰高木。互離為巢。在澤水中。故曰腐巢。訟之解雲。南徒無廬。鳥破其巢。解上震。震為南為徒。下坎為室。震在坎外。故曰南徒無廬。互離為鳥為巢。而坎為破。故曰烏破其巢。以離為巢。庶得真解。</p>',27)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
